#!/usr/bin/env python3

"""Async Registry Pretty Printer

This script allows a user to print the async stacktraces from server_url/_admin/async-registry as a list of trees.

Usage: curl -s server_url/_admin/async-registry | ./pretty_printer.py

"""

import sys
import json
from typing import List
from typing import Optional
from asyncregistry.stacktrace import Stacktrace

class Thread(object):
    def __init__(self, name: str, id: int):
        self.name = name
        self.id = id
    @classmethod
    def from_json(cls, blob: dict):
        return cls(blob["name"], blob["LWPID"])
    def __str__(self):
        return self.name + "(" + str(self.id) + ")"

class SourceLocation(object):
    def __init__(self, file_name: str, line: int, function_name: str):
        self.file_name = file_name
        self.line = line
        self.function_name = function_name
    @classmethod
    def from_json(cls, blob: dict):
        return cls(blob["file_name"], blob["line"], blob["function_name"])
    def __str__(self):
        return self.function_name + " (" + self.file_name + ":" + str(self.line) + ")"

class Requester(object):
    def __init__(self, is_sync: bool, item: int):
        self.is_sync = is_sync
        self.item = item
    @classmethod
    def from_json(cls, blob: dict):
        if not blob:
            return None
        sync = blob.get("thread")
        if sync is not None:
            return cls(True, sync)
        else:
            return cls(False, blob["promise"])
    def __str__(self):
        if self.is_sync:
            # a sync requester is always at the bottom of a tree,
            # but has no entry on its own,
            # therefore just add it here in a new line
            return "\n" + "─ " + str(Thread.from_json(self.item))
        else:
            return ""

class Data(object):
    def __init__(self, owning_thread: Thread, source_location: SourceLocation, id: int, state: str, requester: Requester):
        self.owning_thread = owning_thread
        self.source_location = source_location
        self.id = id
        self.waiter = requester
        self.state = state
    @classmethod
    def from_json(cls, blob: dict):
        return cls(Thread.from_json(blob["owning_thread"]), SourceLocation.from_json(blob["source_location"]), blob["id"], blob["state"], Requester.from_json(blob["requester"]))
    def __str__(self):
        waiter_str = str(self.waiter) if self.waiter != None else ""
        return str(self.source_location) + ", " + str(self.owning_thread) + ", " + self.state + waiter_str

class Promise(object):
    def __init__(self, hierarchy: int, data: Data):
        self.hierarchy = hierarchy
        self.data = data

def main():
    string = sys.stdin.read()
    data = json.loads(string)["promise_stacktraces"]
    first = True
    for promise_list in data:
        current_stacktrace = Stacktrace()
        for promise_entry in promise_list:
            stacktrace = current_stacktrace.append(promise_entry["hierarchy"], promise_entry["data"])
            if stacktrace != None:
                if not first:
                    print("\n")
                print("\n".join(ascii + str(Data.from_json(promise)) for (ascii, promise) in stacktrace))
                first = False
                current_stacktrace = Stacktrace()

if __name__ == '__main__':
    main()

from typing import Optional, Any

def branching_symbol(hierarchy:int, previous_hierarchy: Optional[int]) -> str:
    if hierarchy == previous_hierarchy:
        return "├"
    else:
        return "┌"

def branch_ascii(hierarchy: int, continuations: list) -> str:
    ascii = [" " for x in range(2*hierarchy+2)] + [branching_symbol(hierarchy, continuations[-1] if len(continuations) > 0 else None)] + [" "]
    for continuation in continuations:
        if continuation < hierarchy:
            ascii[2*continuation] = "│"
    return ''.join(ascii)

class Stacktrace(object):
    def __init__(self):
        self.lines = []
        self.stack = [] # hierarchy stack, includes hierarchies that are not yet finished

    def append(self, hierarchy: int, promise: Any) -> Optional[list[str, Any]]:
        # pop finished hierarchy
        if len(self.stack) > 0 and hierarchy < self.stack[-1]:
            self.stack.pop()

        ascii = branch_ascii(hierarchy, self.stack)

        # push current but not if already on stack
        if len(self.stack) == 0 or hierarchy != self.stack[0]:
            self.stack.append(hierarchy)

        self.lines.append((ascii, promise))

        if (hierarchy == 0):
            return self.lines

        return None

"""Async Registry Pretty Printer for gdb

Parsing 

"""
from asyncregistry.gdb_data import AsyncRegistry, Promise
from asyncregistry.gdb_forest import Forest
from asyncregistry.stacktrace import Stacktrace

class AsyncRegistryPrinter:
    def __init__(self, value):
        self._registry = AsyncRegistry.from_gdb(value)

    def to_string (self):
        self.forest = Forest.from_promises(map(lambda promise: (promise.id, promise.requester.content, promise), filter(lambda promise: promise.is_valid(), self._registry.promises())))
        return "async registry"

    def children(self):
        '''One child is one stacktrace per thread'''
        current_stacktrace = Stacktrace()
        for (hierarchy, promise_id, data) in self.forest:
            stacktrace = current_stacktrace.append(hierarchy, data)
            if stacktrace != None:
                current_stacktrace = Stacktrace()
                # there is always a synchronous thread waiting for the root async observable
                waiting_thread = data.requester.content
                stacktrace.append(("─ ", str(waiting_thread)))
                yield ("\n[%s]" % str(waiting_thread), "\n" + "\n".join(ascii + str(promise) for (ascii, promise) in stacktrace))

def async_registry (val):
    if str(val.type) == 'arangodb::async_registry::Registry':
        return AsyncRegistryPrinter(val)
    return None

gdb.pretty_printers.append (async_registry)

from typing import Iterable, Any
from asyncregistry.gdb_data import Promise, PromiseId, Thread

Id = str
class Forest:
    def __init__(self, parents: [Id | None], nodes: [Any], positions: {Id: int}, roots: [Id]):
        self._parents = parents # all parents promise ids
        self._nodes = nodes # all nodes
        self._positions = positions # lookup table for parent and node per promise id
        self._roots = roots
        self._index = None

    def data(self, id: Id) -> Any:
        return self._nodes[self._positions[id]]

    def index(self):
        children = [[] for _ in range(len(self._parents))]
        for id, position in self._positions.items():
            parent = self._parents[position]
            if parent != None and parent in self._positions.keys():
                parent_position = self._positions[parent]
                children[parent_position].append(id)
        self._index = children

    def children(self, id: Id) -> Iterable[Id]:
        if id not in self._positions:
            return None
        position = self._positions[id]
        if position != None and self._index != None:
            for child in self._index[position]:
                yield child

    @classmethod
    def from_promises(cls, promises: Iterable[tuple[PromiseId, PromiseId, Any]]):
        parents: [Id] = [] # all parents promise ids
        nodes: [Any] = [] # all nodes
        positions: {Id: int} = {} # lookup table for parent and node per promise id
        roots: [Id] = []

        count = 0
        for (promise, parent, data) in promises:
            promise_id = str(promise.id)
            positions[promise_id] = count
            nodes.append(data)
            if type(parent) == Thread:
                parents.append(None)
                roots.append(promise_id)
            else:
                parents.append(str(parent.id))
            count += 1

        forest = cls(parents, nodes, positions, roots)
        forest.index()

        return forest


    def dfs(self, start: Id) -> Iterable[tuple[int, Id, Promise]]:
        stack: tuple[Id, int, bool] = [(start, 0, False)]
        while len(stack) != 0:
            (id, hierarchy, hasChildrenProcessed) = stack.pop()
            if hasChildrenProcessed:
                yield (hierarchy, id, self.data(id))
            else:
                stack.append((id, hierarchy, True))
                stack.extend([(child, hierarchy+1, False) for child in self.children(id)])

    def __iter__(self) -> Iterable[tuple[int, Id, Promise]]:
        if (self._index == None):
            return None
        for root in self._roots:
            yield from self.dfs(root)

from __future__ import annotations
from typing import Iterable
from dataclasses import dataclass

@dataclass
class State:
    name: str

    @classmethod
    def from_gdb(cls, value: gdb.Value):
        return cls(str(value['_M_i']))

    def is_deleted(self):
        return self.name == "arangodb::async_registry::State::Deleted"

    def __str__(self):
        if len(self.name) > len("arangodb::async_registry::State::"):
            return self.name[len("arangodb::async_registry::State::"):]
        else:
            return self.name

@dataclass
class Thread:
    posix_id: gdb.Value
    lwpid: gdb.Value
    # TODO is there a way to get the thread name?

    @classmethod
    def from_gdb(cls, value: gdb.Value):
        return cls(value['posix_id'], value['kernel_id'])

    def __str__(self):
        return "thread " + str(self.lwpid)

@dataclass
class SourceLocation:
    file_name: gdb.Value
    function_name: gdb.Value
    line: gdb.Value

    @classmethod
    def from_gdb(cls, value: gdb.Value):
        return cls(value['file_name'], value['function_name'], value['line']['_M_i'])

    def __str__(self):
        return str(self.function_name) + " (" +  str(self.file_name) + ":" + str(self.line) + ")"

@dataclass
class Requester:
    content: Thread | PromiseId

    @classmethod
    def from_gdb(cls, value: gdb.Value):
       alternative = value['_M_index']
       if alternative == 0:
           content = Thread.from_gdb(value['_M_u']['_M_first']['_M_storage'])
       elif alternative == 1:
           content = PromiseId(value['_M_u']['_M_rest']['_M_first']['_M_storage'])
       else:
           return "wrong input"
       return cls(content)

    def __str__(self):
        return str(self.content)

@dataclass
class PromiseId:
    id: gdb.Value

    def __init__(self, id):
        self.id = id

    def __equ__(self, other: PromiseId) -> bool:
       return self.id == other.id 

    def __str__(self):
        return str(self.id)

@dataclass
class Promise:
    id: PromiseId
    thread: Thread
    source_location: SourceLocation
    requester: Requester
    state: State

    @classmethod
    def from_gdb(cls, value_ptr: gdb.Value):
        value = value_ptr.dereference()
        return cls(
            PromiseId(value_ptr),
            Thread.from_gdb(value["thread"]),
            SourceLocation.from_gdb(value["source_location"]),
            Requester.from_gdb(value["requester"]['_M_i']),
            State.from_gdb(value["state"])
        )

    def is_valid(self):
        return not self.state.is_deleted()

    def __str__(self):
        return str(self.source_location) + ", " + str(self.thread) + ", " + str(self.state)

@dataclass
class GdbAtomicList:
    _head_ptr: gdb.Value

    def __iter__(self):
        current = self._head_ptr
        next = current
        while next != 0:
            current = next
            next = current.dereference()["next"]
            yield current

@dataclass
class ThreadRegistry:
    promises: Iterable[Promise]

    @classmethod
    def from_gdb(cls, value: gdb.Value):
        return cls(Promise.from_gdb(promise) for promise in GdbAtomicList(value["promise_head"]["_M_b"]["_M_p"]))

class GdbVector:
    def __init__(self, value: gdb.Value):
        self._begin = value["_M_start"]
        self._end = value["_M_finish"]

    def __iter__(self):
        current = self._begin
        while current != self._end:
            registry = current.dereference()["_M_ptr"].dereference()
            current += 1
            yield registry

@dataclass
class AsyncRegistry:
    thread_registries: Iterable[ThreadRegistry]

    @classmethod
    def from_gdb(cls, value: gdb.Value):
        return cls(ThreadRegistry.from_gdb(registry) for registry in GdbVector(value['registries']['_M_impl']))

    def promises(self) -> Iterable[Promise]:
        for registry in self.thread_registries:
            for promise in registry.promises:
                yield promise

