        self.store = []  # used to store the metrics
        self.timestamps = []  # used to store the timestamps

    def addSpecificMetric(self, metric):
        self.metricsNames.append(metric)

    def addSpecificMetrics(self, metrics):
        self.metricsNames.extend(metrics)

    def filterMetric(self, actualMetricName):
        if len(self.metricsNames) > 0:
            for filterName in self.metricsNames:
                if filterName in actualMetricName:
                    return False
        else:
            return True

        return True

    def getMetric(self, store):
        timestamp = time.time()
        self.timestamps.append(timestamp)
        try:
            metrics = requests.get(self.endpoint).text
            for family in text_string_to_metric_families(metrics):
                for sample in family.samples:
                    # Check Filters
                    if self.filterMetric(sample.name):
                        continue

                    timedSample = Sample(sample.name, sample.labels, sample.value, timestamp)
                    store.append(timedSample)
        except Exception as e:
            print(e)

    def watchDog(self, store, stopEvent):
        while not stopEvent.is_set():
            self.getMetric(store)
            time.sleep(self.interval)

    def start(self):
        self.daemon = Thread(target=self.watchDog, daemon=True, name='WatchDog', args=(self.store, self.stopEvent))
        self.daemon.start()

    def stop(self):
        self.stopEvent.set()

    def metricsToGraph(self, dictData, fileName):
        for metric in dictData:
            if "bucket" in metric:
                warnings.warn("Metric: " + metric + " is a bucket metric and will not be plotted.")
                continue
            else:
                pngFileName = fileName + "-" + metric + ".png"
                plotValues = []
                plotTimestamps = []
                for value in dictData[metric]["values"]:
                    plotValues.append(value[1])
                    plotTimestamps.append(value[0])

                # Metrics to file as plot data
                fig, ax = plt.subplots()
                t = plotTimestamps
                s = np.array(plotValues)
                fmt = ticker.FuncFormatter(lambda x, pos: time.strftime('%H:%M:%S', time.gmtime(x)))
                ax.xaxis.set_major_formatter(fmt)
                ax.plot(t, s)
                ax.set(xlabel='time (s)', ylabel='probably bytes (check docu)',
                       title=metric)
                ax.grid()
                fig.savefig(pngFileName)
                plt.close()

    def metricsToFile(self, jsonFile, fileName):
        convertedDict = {}

        for sample in self.store:
            if sample.name in convertedDict:
                convertedDict[sample.name]["values"].append(
                    [sample.timestamp, sample.value]
                )
            else:
                convertedDict[sample.name] = {
                    "values": [[sample.timestamp, sample.value, ]]
                }

        # Metrics to file as json
        jsonFile.write(json.dumps(convertedDict))
        self.metricsToGraph(convertedDict, fileName)

    def write(self, fileName):
        timeString = time.strftime("%Y%m%d-%H%M%S")
        jsonFileName = self.workDir + "/metrics/" + fileName + "-" + timeString + ".json"
        pngDirName = self.workDir + "/metrics/plots/"
        pngPartialFileName = pngDirName + fileName + "-" + timeString
        os.makedirs(os.path.dirname(jsonFileName), exist_ok=True)
        os.makedirs(os.path.dirname(pngPartialFileName), exist_ok=True)
        with open(jsonFileName, "w") as file:
            self.metricsToFile(file, pngPartialFileName)

    def stopAndWrite(self, fileName):
        self.stop()
        self.write(fileName)

from .Agent import Agent
from .Coordinator import Coordinator
from .DBServer import DBServer


class ArangodEnvironment:
    """An environment for starting arangod processes
    """

    def __init__(self, binary, topdir, workdir, initial_port=8500):
        self.binary = binary
        self.topdir = topdir
        self._workdir = workdir
        self._next_port = initial_port
        self._address = "127.0.0.1"
        self._transport = "tcp"
        self._agents = []
        self._coordinators = []
        self._dbservers = []

    def __del__(self):
        self.shutdown()

    def shutdown(self):
        for dbserver in self._dbservers:
            dbserver.shutdown()
        for coordinator in self._coordinators:
            coordinator.shutdown()
        for agent in self._agents:
            agent.shutdown()

    def get_next_port(self):
        result = self._next_port
        self._next_port = self._next_port + 1
        return result

    def start_agent(self):
        agent = Agent(self)
        agent.start()

    def register_agent(self, agent):
        self._agents.append(agent)

    def start_coordinator(self):
        coordinator = Coordinator(self)
        coordinator.start()

    def register_coordinator(self, coordinator):
        self._coordinators.append(coordinator)

    def start_dbserver(self):
        dbserver = DBServer(self)
        dbserver.start()

    def register_dbserver(self, dbserver):
        self._dbservers.append(dbserver)

    def insert_cluster_agency_endpoints(self, param):
        for agent in self._agents:
            param["--cluster.agency-endpoint"] = agent.get_endpoint()

    def get_coordinator_http_endpoint(self):
        return self._coordinators[0].get_http_endpoint()

import json
import os.path as path
import subprocess

def flatten_dict(d):
    result = []
    for k, v in d.items():
        result.append(k)
        result.append(v)
    return result

class ArangodServer:
    """A supervisor object for an arangod process
    """
    def __init__(self, environment):
        self._environment = environment
        self._proc = None
        self._port = environment.get_next_port()

    def __del__(self):
        self.shutdown()

    def collect_parameters(self, param):
        param["-c"] = "none"
        param["--server.authentication"] = "false"
        param["--database.directory"] = path.join(self._environment._workdir, f"data{self._port}")
        param["--log.role"] = "true"
        param["--log.file"] = path.join(self._environment._workdir, f"{self._port}.log")
        param["--server.endpoint"] = self.get_endpoint()

    def get_endpoint(self):
        return f"tcp://127.0.0.1:{self._port}"

    def get_http_endpoint(self):
        return f"http://127.0.0.1:{self._port}"

    def start(self, silent=True):
        param = {}
        self.collect_parameters(param)
        if silent:
            self._proc = subprocess.Popen([self._environment.binary] + flatten_dict(param),
                                          stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        else:
            print(json.dumps(param, indent=4))
            self._proc = subprocess.Popen([self._environment.binary] + flatten_dict(param))

    def shutdown(self):
        if self._proc is not None:
            self._proc.terminate()
            self._proc.wait()
            self._proc = None

#!/bin/env python3
""" manipulate processes """
import time
import json
import sys
import logging
import psutil

def list_all_processes():
    """list all processes for later reference"""
    pseaf = "PID  Process"
    # pylint: disable=catching-non-exception
    for process in psutil.process_iter(["pid", "ppid", "name"]):
        if  process.pid in [1, 2] or process.ppid() == 2:
            continue
        cmdline = process.name
        try:
            cmdline = str(process.cmdline())
            if cmdline == "[]":
                cmdline = "[" + process.name() + "]"
        except psutil.AccessDenied:
            pass
        except psutil.ProcessLookupError:
            pass
        except psutil.NoSuchProcess:
            pass
        logging.info("PID: %s PPID: %s %s", process.pid, process.ppid(), cmdline)
    logging.info(pseaf)
    sys.stdout.flush()

def kill_all_arango_processes():
    """list all processes for later reference"""
    # pylint: disable=catching-non-exception
    for process in psutil.process_iter(["pid", "name"]):
        if (
            process.name().lower().find("arango") >= 0
            or process.name().lower().find("tshark") >= 0
        ):
            try:
                logging.info("Main: killing %s - %s", process.name(), str(process.pid))
                process.resume()
            except psutil.NoSuchProcess:
                pass
            except psutil.AccessDenied:
                pass
            try:
                process.kill()
            except psutil.NoSuchProcess:  # pragma: no cover
                pass

def gather_process_thread_statistics(p):
    """ gather the statistics of one process and all its threads """
    ret = {}
    ret['process'] = [{
        'time': time.ctime(),
        'pid': p.pid,
        'ppid': p.ppid(),
        'cmdline': p.cmdline(),
        'name': p.name(),
        'percent': p.cpu_percent(),
        'iocounters': p.io_counters(),
        'ctxSwitches': p.num_ctx_switches(),
        'numfds': p.num_fds(),
        'cpu_times': p.cpu_times(),
        'meminfo': p.memory_full_info(),
        'netcons': p.connections()
    }]
    for t in p.threads():
        ret[ t.id ] = { 'user': t.user_time, 'sys': t.system_time}
    return ret

def add_delta(p1, p2):
    """ calculate and add a delta in cpu and time to all threads of a process """
    tids = list(p1.keys())
    for tid in tids:
        if tid in p2 and tid != 'process':
            p1[tid]['d_user'] = p2[tid]['user'] - p1[tid]['user']
            p1[tid]['d_sys'] = p2[tid]['sys'] - p1[tid]['sys']
    p1['process'].append(p2['process'][0])

def get_all_processes_stats_json(load):
    """ aggregate a structure of all processes and their threads plus delta """
    # pylint: disable=broad-exception-caught
    process_full_list = {}
    process_full_list['sys'] = {
        'load': load,
        'vmem': psutil.virtual_memory(),
        'mem': psutil.swap_memory(),
        'diskio': psutil.disk_io_counters(perdisk=True, nowrap=True),
        'netio': psutil.net_io_counters(pernic=True, nowrap=True),
    }
    processes = psutil.process_iter()
    for process in processes:
        name = ""
        try:
            name = process.name()
            if  process.pid not in [1, 2] and process.ppid() != 2:
                procstat = gather_process_thread_statistics(process)
                process_full_list[f"p{process.pid}"] = procstat
        except psutil.AccessDenied:
            pass
        except Exception as ex:
            print(f"while inspecting {name}: {ex} ")
    return json.dumps(process_full_list)
